int fds[2];
pipe(fds);              // fds[0] is the read end, fds[1] is the write end

pid_t pid = fork();
if (pid === 0) {
    close(fds[1]);       // child only reads, close its write end
    char buf[100];
    read(fds[0], buf, 100);
} else {
    close(fds[0]);       // parent only writes, close its read end
    write(fds[1], "hello", 5);
}

